import asyncio
import functools
import inspect
import sys

if sys.version_info >= (3, 13):
    from inspect import iscoroutinefunction
else:
    from asyncio import iscoroutinefunction

def _is_async_callable(call):
    if call is None:
        return False
    calls = [call]
    while True:
        current = calls[-1]
        if isinstance(current, functools.partial):
            next_call = current.func
        elif hasattr(current, "__wrapped__"):
            next_call = current.__wrapped__
        else:
            break
        if next_call in calls:
            break
        calls.append(next_call)

    for call in calls:
        if inspect.isroutine(call):
            if iscoroutinefunction(call):
                return True
        elif not inspect.isclass(call):
            dunder_call = getattr(call, "__call__", None)
            if iscoroutinefunction(dunder_call):
                return True
    return False

async def async_func():
    return "async"

def sync_func():
    return "sync"

def wrapper(f):
    @functools.wraps(f)
    def wrapped(*args, **kwargs):
        return f(*args, **kwargs)
    return wrapped

def test_is_async_callable():
    assert _is_async_callable(async_func) is True
    assert _is_async_callable(sync_func) is False
    assert _is_async_callable(wrapper(async_func)) is True
    assert _is_async_callable(wrapper(sync_func)) is False
    assert _is_async_callable(functools.partial(async_func)) is True
    assert _is_async_callable(functools.partial(sync_func)) is False
    assert _is_async_callable(wrapper(functools.partial(async_func))) is True
    assert _is_async_callable(functools.partial(wrapper(async_func))) is True
    assert _is_async_callable(wrapper(wrapper(async_func))) is True
    print("is_async_callable tests passed")

if __name__ == "__main__":
    test_is_async_callable()
    print("All tests passed")

